import * as React from 'react';
import { afterAll, afterEach, describe, expect, it, vi } from 'vitest';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseFieldControl } from './BaseFieldControl';

const observations: Record<string, unknown> = {};

afterEach(() => {
  cleanup();
});

afterAll(() => {
  // eslint-disable-next-line no-console
  console.log(`OBSERVATIONS ${JSON.stringify(observations, null, 2)}`);
});

function measureRenders(
  Control: React.ComponentType<any>,
  rootProps: Record<string, unknown>,
): { first: number; steadyPerTwoKeystrokes: number } {
  const renderCountRef = { current: 0 };

  function App() {
    const [value, setValue] = React.useState('');
    return (
      <Field.Root {...rootProps}>
        <Control
          data-testid="control"
          value={value}
          onValueChange={setValue}
          render={(props: any) => {
            renderCountRef.current += 1;
            return <input {...props} />;
          }}
        />
      </Field.Root>
    );
  }

  render(<App />);
  const control = screen.getByTestId('control');
  const mounted = renderCountRef.current;

  fireEvent.change(control, { target: { value: 'a' } });
  const settled = renderCountRef.current;

  fireEvent.change(control, { target: { value: 'ab' } });
  fireEvent.change(control, { target: { value: 'abc' } });

  return { first: settled - mounted, steadyPerTwoKeystrokes: renderCountRef.current - settled };
}

describe('probe', () => {
  it('A/B: controlled render counts, HEAD vs BASE, default mode and onChange mode', () => {
    const validate = () => null;
    observations.renders_HEAD_default = measureRenders(Field.Control, {});
    cleanup();
    observations.renders_BASE_default = measureRenders(BaseFieldControl, {});
    cleanup();
    observations.renders_HEAD_onChange = measureRenders(Field.Control, {
      validationMode: 'onChange',
      validate,
    });
    cleanup();
    observations.renders_BASE_onChange = measureRenders(BaseFieldControl, {
      validationMode: 'onChange',
      validate,
    });
    expect(true).toBe(true);
  });

  it('C: programmatic controlled change and a Form server error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>
            set
          </button>
        </Form>
      );
    }

    render(<App />);
    const before = screen.queryByText('Server error') != null;
    fireEvent.click(screen.getByRole('button'));
    const after = screen.queryByText('Server error') != null;
    observations.C_serverError_programmatic = { before, after };
    expect(true).toBe(true);
  });

  it('D: prevented change on a controlled control', () => {
    const validate = vi.fn(() => null);

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }

    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), {
      capture: true,
      once: true,
    });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });

    observations.D_prevented_controlled_HEAD = {
      validateCalls: validate.mock.calls.length,
      serverErrorStillShown: screen.queryByText('Server error') != null,
      domValue: control.value,
    };
    expect(true).toBe(true);
  });

  it('D2: prevented change on a controlled control at BASE', () => {
    const validate = vi.fn(() => null);

    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <BaseFieldControl value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }

    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), {
      capture: true,
      once: true,
    });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });

    observations.D2_prevented_controlled_BASE = {
      validateCalls: validate.mock.calls.length,
      serverErrorStillShown: screen.queryByText('Server error') != null,
      domValue: control.value,
    };
    expect(true).toBe(true);
  });

  it('E: programmatic change resolving a visible error (onBlur mode)', () => {
    function App() {
      const [value, setValue] = React.useState('bad');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(v) => (v === 'bad' ? 'custom error' : null)}
        >
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
          <button type="button" onClick={() => setValue('good')}>
            set
          </button>
        </Field.Root>
      );
    }

    render(<App />);
    const control = screen.getByRole('textbox');
    fireEvent.focus(control);
    fireEvent.blur(control);
    const errorBefore = screen.queryByText('custom error') != null;
    fireEvent.click(screen.getByRole('button'));
    const errorAfter = screen.queryByText('custom error') != null;
    observations.E_error_after_programmatic_fix = {
      errorBefore,
      errorAfter,
      rootInvalidAfter: screen.getByTestId('root').hasAttribute('data-invalid'),
    };
    expect(true).toBe(true);
  });

  it('F: consumer rejects or rewrites a controlled keystroke', () => {
    const validate = vi.fn((_value: unknown) => null);

    function Reject() {
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value="" onValueChange={() => {}} />
        </Field.Root>
      );
    }

    render(<Reject />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    observations.F_reject_HEAD = {
      validateCalls: validate.mock.calls.length,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
    };
    cleanup();
    validate.mockClear();

    function RejectBase() {
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <BaseFieldControl value="" onValueChange={() => {}} />
        </Field.Root>
      );
    }

    render(<RejectBase />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const rootBase = screen.getByTestId('root');
    observations.F_reject_BASE = {
      validateCalls: validate.mock.calls.length,
      dirty: rootBase.hasAttribute('data-dirty'),
      filled: rootBase.hasAttribute('data-filled'),
    };
    cleanup();
    validate.mockClear();

    function Rewrite() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={(next) => setValue(next.toUpperCase())} />
        </Field.Root>
      );
    }

    render(<Rewrite />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    observations.F_rewrite_HEAD = {
      validateCalls: validate.mock.calls.length,
      lastValue: validate.mock.lastCall?.[0],
    };
    expect(true).toBe(true);
  });

  it('G: canceled change, uncontrolled and controlled', () => {
    const validate = vi.fn((_value: unknown) => null);

    render(
      <Form errors={{ message: 'Server error' }}>
        <Field.Root data-testid="root" name="message" validationMode="onChange" validate={validate}>
          <Field.Control onValueChange={(_value, details) => details.cancel()} />
          <Field.Error />
        </Field.Root>
      </Form>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    observations.G_cancel_uncontrolled_HEAD = {
      validateCalls: validate.mock.calls.length,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
      serverErrorStillShown: screen.queryByText('Server error') != null,
    };
    cleanup();
    validate.mockClear();

    function Controlled() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root
            data-testid="root"
            name="message"
            validationMode="onChange"
            validate={validate}
          >
            <Field.Control
              value={value}
              onValueChange={(next, details) => {
                details.cancel();
                setValue(next);
              }}
            />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }

    render(<Controlled />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const rootControlled = screen.getByTestId('root');
    observations.G_cancel_controlled_HEAD = {
      validateCalls: validate.mock.calls.length,
      dirty: rootControlled.hasAttribute('data-dirty'),
      filled: rootControlled.hasAttribute('data-filled'),
      serverErrorStillShown: screen.queryByText('Server error') != null,
    };
    expect(true).toBe(true);
  });

  it('H: controlled value reset to null or undefined after being filled', () => {
    function App() {
      const [value, setValue] = React.useState<string | undefined>('abc');
      return (
        <Field.Root data-testid="root">
          <Field.Control value={value as any} onValueChange={setValue} />
          <button type="button" onClick={() => setValue(null as any)}>
            reset
          </button>
        </Field.Root>
      );
    }

    const error = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(<App />);
    const root = screen.getByTestId('root');
    const filledBefore = root.hasAttribute('data-filled');
    fireEvent.click(screen.getByRole('button'));
    observations.H_null_reset_HEAD = {
      filledBefore,
      filledAfter: root.hasAttribute('data-filled'),
      domValue: screen.getByRole<HTMLInputElement>('textbox').value,
    };
    error.mockRestore();
    expect(true).toBe(true);
  });
});

