import * as React from 'react';
import { describe, it, expect } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControlBase } from './FieldControlBase';

const variants: Array<[string, React.ElementType]> = [
  ['HEAD', Field.Control],
  ['BASE', FieldControlBase as any],
];

function log(label: string, data: unknown) {
  // eslint-disable-next-line no-console
  console.log(`OBS ${label} ${JSON.stringify(data)}`);
}

describe.each(variants)('%s', (label, Control) => {
  it('A: renders per keystroke, controlled + validationMode=onChange', () => {
    const renders: any[] = [];
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root
          validationMode="onChange"
          validate={(v) => (String(v).length > 2 ? 'too long' : null)}
        >
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props: any, state: any) => {
              renders.push([props.value, state.valid, state.dirty, state.filled]);
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    const perKey: any[] = [];
    for (const next of ['a', 'ab', 'abc', 'abcd', 'abcde']) {
      const before = renders.length;
      fireEvent.change(control, { target: { value: next } });
      perKey.push({ next, count: renders.length - before, renders: renders.slice(before) });
    }
    log(`${label} A`, perKey);
    cleanup();
  });

  it('A2: renders per keystroke, controlled + default validationMode (onSubmit, no attempt)', () => {
    let count = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root>
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props: any) => {
              count += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    const perKey: number[] = [];
    for (const next of ['a', 'ab', 'abc']) {
      const before = count;
      fireEvent.change(control, { target: { value: next } });
      perKey.push(count - before);
    }
    log(`${label} A2`, perKey);
    cleanup();
  });

  it('C: unmount while focused', () => {
    let hide: () => void = () => {};
    function App() {
      const [show, setShow] = React.useState(true);
      hide = () => setShow(false);
      return (
        <Field.Root data-testid="root">
          {show && <Control data-testid="control" />}
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    act(() => control.focus());
    const before = screen.getByTestId('root').hasAttribute('data-focused');
    act(() => hide());
    const after = screen.getByTestId('root').hasAttribute('data-focused');
    log(`${label} C`, {
      focusedBeforeUnmount: before,
      focusedAfterUnmount: after,
      controlStillMounted: !!screen.queryByTestId('control'),
    });
    cleanup();
  });

  it('D: disabled while focused', () => {
    let disable: () => void = () => {};
    function App() {
      const [disabled, setDisabled] = React.useState(false);
      disable = () => setDisabled(true);
      return (
        <Field.Root data-testid="root">
          <Control data-testid="control" disabled={disabled} />
