import * as React from 'react';
import { afterEach, describe, expect, it } from 'vitest';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseFieldControl } from './BaseFieldControl';

afterEach(() => cleanup());

const variants = [
  ['HEAD', Field.Control],
  ['BASE', BaseFieldControl],
] as const;

function snap(el: HTMLElement) {
  return ['data-invalid', 'data-valid', 'data-dirty', 'data-filled', 'data-focused', 'data-touched']
    .filter((a) => el.hasAttribute(a))
    .join(' ');
}

describe.each(variants)('%s', (label, Control: any) => {
  it('T1 post-submit programmatic clear of required controlled input', async () => {
    let submitted = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form
          onFormSubmit={() => {
            submitted += 1;
            setValue('');
          }}
        >
          <Field.Root name="title" data-testid="root">
            <Control required value={value} onValueChange={setValue} data-testid="control" />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    const { container } = render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.change(control, { target: { value: 'abc' } });
    const beforeSubmit = snap(screen.getByTestId('root'));
    fireEvent.submit(container.querySelector('form')!);
    await act(async () => {});
    console.log(
      `[${label}] T1 submitted=${submitted} domValue=${JSON.stringify(control.value)} before=[${beforeSubmit}] after=[${snap(screen.getByTestId('root'))}] aria-invalid=${control.getAttribute('aria-invalid')} valueMissing=${control.validity.valueMissing}`,
    );
    expect(true).toBe(true);
  });

  it('T1b onChange mode: clear button on required controlled input', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" data-testid="root">
          <Control required value={value} onValueChange={setValue} data-testid="control" />
          <button type="button" onClick={() => setValue('')}>
            clear
          </button>
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.change(control, { target: { value: 'abc' } });
    fireEvent.click(screen.getByRole('button'));
    await act(async () => {});
    console.log(`[${label}] T1b after clear=[${snap(screen.getByTestId('root'))}]`);
  });

  it('T2 render count per keystroke, controlled + validationMode=onChange', async () => {
    let renders = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props: any) => {
              renders += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    await act(async () => {});
    const settled = renders;
    fireEvent.change(control, { target: { value: 'ab' } });
    await act(async () => {});
    fireEvent.change(control, { target: { value: 'abc' } });
    await act(async () => {});
    console.log(`[${label}] T2 renders for 2 steady-state keystrokes = ${renders - settled}`);
  });

  it('T3 focused control becomes disabled / unmounts', async () => {
    function App({ disabled, show }: { disabled: boolean; show: boolean }) {
      return (
        <Field.Root data-testid="root">
          {show ? <Control data-testid="control" disabled={disabled} /> : null}
        </Field.Root>
      );
    }
    const { rerender } = render(<App disabled={false} show />);
    const control = screen.getByTestId('control');
    act(() => control.focus());
    const focusedBefore = snap(screen.getByTestId('root'));
    rerender(<App disabled show />);
    const afterDisable = snap(screen.getByTestId('root'));
    cleanup();

    const r2 = render(<App disabled={false} show />);
    act(() => screen.getByTestId('control').focus());
    r2.rerender(<App disabled={false} show={false} />);
    const afterUnmount = snap(screen.getByTestId('root'));
    console.log(
      `[${label}] T3 focused=[${focusedBefore}] afterDisable=[${afterDisable}] afterUnmount=[${afterUnmount}]`,
    );
  });

  it('T4 programmatic change vs Form server error', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      const [errors, setErrors] = React.useState<Record<string, string>>({ message: 'Server error' });
      return (
        <Form errors={errors}>
          <Field.Root name="message" data-testid="root">
            <Control value={value} onValueChange={setValue} data-testid="control" />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" data-testid="set" onClick={() => setValue('external')}>
            set
          </button>
          <button
            type="button"
            data-testid="both"
            onClick={() => {
              setErrors({ message: 'Second server error' });
              setValue('normalized');
            }}
          >
            both
          </button>
        </Form>
      );
    }
    render(<App />);
    const before = screen.queryByTestId('error')?.textContent ?? null;
    fireEvent.click(screen.getByTestId('set'));
    await act(async () => {});
    const afterSet = screen.queryByTestId('error')?.textContent ?? null;
    fireEvent.click(screen.getByTestId('both'));
    await act(async () => {});
    const afterBoth = screen.queryByTestId('error')?.textContent ?? null;
    console.log(
      `[${label}] T4 errorBefore=${JSON.stringify(before)} afterProgrammaticSet=${JSON.stringify(afterSet)} afterErrorsAndValueSameCommit=${JSON.stringify(afterBoth)}`,
    );
  });

  it('T5 keyed remount of controlled control with empty value', async () => {
    function App({ step }: { step: number }) {
      const values = ['filled', ''];
      return (
        <Field.Root data-testid="root">
          <Control key={step} value={values[step]} onValueChange={() => {}} data-testid="control" />
        </Field.Root>
      );
    }
    const { rerender } = render(<App step={0} />);
    const first = snap(screen.getByTestId('root'));
    rerender(<App step={1} />);
    console.log(`[${label}] T5 step0=[${first}] step1(empty)=[${snap(screen.getByTestId('root'))}]`);
  });

  it('T6 uncontrolled cancel: dirty/filled still applied', async () => {
    render(
      <Field.Root data-testid="root" validationMode="onChange">
        <Control data-testid="control" onValueChange={(_v: string, d: any) => d.cancel?.()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByTestId('control'), { target: { value: 'a' } });
    console.log(`[${label}] T6 after canceled change=[${snap(screen.getByTestId('root'))}]`);
  });
});
