import * as React from 'react';
import { afterAll, afterEach, describe, it, vi } from 'vitest';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseControl } from './FieldControlBase';

const results: Record<string, Record<string, unknown>> = {};
function record(scenario: string, variant: string, value: unknown) {
  results[scenario] ??= {};
  results[scenario][variant] = value;
}

afterEach(() => cleanup());
afterAll(() => {
  // eslint-disable-next-line no-console
  console.log(`PROBE_RESULTS ${JSON.stringify(results, null, 2)}`);
});

const variants: Array<[string, React.ElementType]> = [
  ['head', Field.Control],
  ['base', BaseControl],
];

describe.each(variants)('%s', (variant, Control) => {
  it('S1 submit then programmatic clear of a required controlled field', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form data-testid="form" onFormSubmit={() => setValue('')}>
          <Field.Root name="title" data-testid="root">
            <Control required value={value} onValueChange={setValue} data-testid="control" />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.change(control, { target: { value: 'buy milk' } });
    fireEvent.submit(screen.getByTestId('form'));
    record('S1_submit_then_clear', variant, {
      inputValue: control.value,
      ariaInvalid: control.getAttribute('aria-invalid'),
      rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
      errorText: screen.queryByTestId('error')?.textContent ?? null,
    });
  });

  it('S2 remount with an empty controlled value after being filled', () => {
    function App() {
      const [value, setValue] = React.useState('abc');
      const [mounted, setMounted] = React.useState(true);
      return (
        <div>
          <Field.Root data-testid="root">
            {mounted && <Control value={value} onValueChange={setValue} data-testid="control" />}
          </Field.Root>
          <button
            type="button"
            onClick={() => {
              setMounted(false);
              setValue('');
            }}
          >
            hide
          </button>
          <button type="button" onClick={() => setMounted(true)}>
            show
          </button>
        </div>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    const before = root.hasAttribute('data-filled');
    fireEvent.click(screen.getByText('hide'));
    fireEvent.click(screen.getByText('show'));
    record('S2_remount_empty', variant, {
      filledBefore: before,
      inputValue: (screen.getByTestId('control') as HTMLInputElement).value,
      filledAfterRemountEmpty: root.hasAttribute('data-filled'),
    });
  });

  it('S3 renders per keystroke, controlled, validationMode=onChange', () => {
    let renders = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange">
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props: any) => {
              renders += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    const settled = renders;
    fireEvent.change(control, { target: { value: 'ab' } });
    fireEvent.change(control, { target: { value: 'abc' } });
    record('S3_renders_per_two_keystrokes_onChange', variant, renders - settled);
  });

  it('S4 focused control becomes disabled / unmounts', () => {
    function App() {
      const [disabled, setDisabled] = React.useState(false);
      const [mounted, setMounted] = React.useState(true);
      return (
        <div>
          <Field.Root data-testid="root">
            {mounted && <Control disabled={disabled} data-testid="control" />}
          </Field.Root>
          <button type="button" onMouseDown={() => setDisabled(true)}>
            disable
          </button>
          <button type="button" onMouseDown={() => setMounted(false)}>
            unmount
          </button>
        </div>
      );
    }
    const first = render(<App />);
    let root = screen.getByTestId('root');
    fireEvent.focus(screen.getByTestId('control'));
    const focusedBefore = root.hasAttribute('data-focused');
    fireEvent.mouseDown(screen.getByText('disable'));
    const afterDisable = root.hasAttribute('data-focused');
    first.unmount();

    render(<App />);
    root = screen.getByTestId('root');
    fireEvent.focus(screen.getByTestId('control'));
    fireEvent.mouseDown(screen.getByText('unmount'));
    record('S4_focus_latch', variant, {
      focusedBefore,
      focusedAfterDisable: afterDisable,
      focusedAfterUnmount: root.hasAttribute('data-focused'),
    });
  });

  it('S5 programmatic controlled change with a Form server error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message">
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>
            set
          </button>
        </Form>
      );
    }
    render(<App />);
    const before = screen.queryByTestId('error')?.textContent ?? null;
    fireEvent.click(screen.getByText('set'));
    record('S5_programmatic_change_server_error', variant, {
      before,
      after: screen.queryByTestId('error')?.textContent ?? null,
    });
  });

  it('S6 value loaded while the control is disabled', () => {
    function App({ sameCommit }: { sameCommit: boolean }) {
      const [value, setValue] = React.useState('');
      const [loading, setLoading] = React.useState(true);
      return (
        <div>
          <Field.Root data-testid="root">
            <Control
              disabled={loading}
              value={value}
              onValueChange={setValue}
              data-testid="control"
            />
          </Field.Root>
          <button
            type="button"
            onClick={() => {
              setValue('loaded');
              if (sameCommit) {
                setLoading(false);
              }
            }}
          >
            load
          </button>
          <button type="button" onClick={() => setLoading(false)}>
            enable
          </button>
        </div>
      );
    }
    const first = render(<App sameCommit />);
    fireEvent.click(screen.getByText('load'));
    const sameCommitDirty = screen.getByTestId('root').hasAttribute('data-dirty');
    // returning to the loaded value later must read pristine if the baseline is 'loaded'
    fireEvent.change(screen.getByTestId('control'), { target: { value: 'loadedX' } });
    fireEvent.change(screen.getByTestId('control'), { target: { value: 'loaded' } });
    const sameCommitDirtyAfterRoundTrip = screen.getByTestId('root').hasAttribute('data-dirty');
    first.unmount();

    render(<App sameCommit={false} />);
    fireEvent.click(screen.getByText('load'));
    fireEvent.click(screen.getByText('enable'));
    const separateDirty = screen.getByTestId('root').hasAttribute('data-dirty');
    fireEvent.change(screen.getByTestId('control'), { target: { value: 'loadedX' } });
    fireEvent.change(screen.getByTestId('control'), { target: { value: 'loaded' } });
    record('S6_load_while_disabled', variant, {
      dirtyAfterLoadAndEnableSameCommit: sameCommitDirty,
      dirtyAfterRoundTripSameCommit: sameCommitDirtyAfterRoundTrip,
      dirtyAfterLoadThenEnable: separateDirty,
      dirtyAfterRoundTripSeparate: screen.getByTestId('root').hasAttribute('data-dirty'),
    });
  });

  it('S7 controlled change whose native event is default-prevented', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole('textbox') as HTMLInputElement;
    control.addEventListener('input', (event) => event.preventDefault(), {
      capture: true,
      once: true,
    });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    record('S7_controlled_default_prevented', variant, {
      inputValue: control.value,
      validateCalls: validate.mock.calls.length,
      errorText: screen.queryByTestId('error')?.textContent ?? null,
    });
  });

  it('S8 uncontrolled change canceled through details.cancel()', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Control onValueChange={(_value: string, details: any) => details.cancel()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    record('S8_uncontrolled_cancel', variant, {
      validateCalls: validate.mock.calls.length,
      dirty: root.hasAttribute('data-dirty'),
      filled: root.hasAttribute('data-filled'),
    });
  });

  it('S9 controlled numeric value: argument passed to validate on submit', () => {
    const validate = vi.fn((_value: unknown) => null);
    function App() {
      const [value, setValue] = React.useState(5);
      return (
        <Form data-testid="form" onFormSubmit={() => {}}>
          <Field.Root name="qty" validate={validate}>
            <Control value={value} onValueChange={(next: string) => setValue(Number(next))} />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    fireEvent.submit(screen.getByTestId('form'));
    record('S9_numeric_validate_arg_on_submit', variant, {
      calls: validate.mock.calls.map((call) => `${typeof call[0]}:${String(call[0])}`),
    });
  });

  it('S10 controlled change that the consumer cancels but still applies', () => {
    const validate = vi.fn((_value: unknown) => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Control
            value={value}
            onValueChange={(next: string, details: any) => {
              details.cancel();
              setValue(next);
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    record('S10_controlled_cancel_but_applied', variant, {
      validateCalls: validate.mock.calls.length,
    });
  });
});

