import * as React from 'react';
import { describe, it } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControlBase } from './FieldControlBase';

const variants: Array<[string, React.ElementType]> = [
  ['HEAD', Field.Control],
  ['BASE', FieldControlBase as any],
];

function log(label: string, data: unknown) {
  // eslint-disable-next-line no-console
  console.log(`OBS ${label} ${JSON.stringify(data)}`);
}

describe.each(variants)('%s', (label, Control) => {
  it('K1: onBlur validation (sync) + consumer normalizes the value in onBlur', () => {
    const seen: unknown[] = [];
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(v) => {
            seen.push(v);
            return String(v).includes('@') ? null : 'Invalid email';
          }}
        >
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            onBlur={() => setValue((v) => v.trim())}
          />
          <Field.Error />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.focus(control);
    fireEvent.change(control, { target: { value: 'foo ' } });
    fireEvent.blur(control);
    log(`${label} K1`, {
      validateCalls: seen,
      inputValue: control.value,
      errorShown: !!screen.queryByText('Invalid email'),
      rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
      rootValid: screen.getByTestId('root').hasAttribute('data-valid'),
      ariaInvalid: control.getAttribute('aria-invalid'),
    });
    cleanup();
  });

  it('K1b: same as K1 without the normalizing onBlur (control case)', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(v) => (String(v).includes('@') ? null : 'Invalid email')}
        >
          <Control data-testid="control" value={value} onValueChange={setValue} />
          <Field.Error />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.focus(control);
    fireEvent.change(control, { target: { value: 'foo ' } });
    fireEvent.blur(control);
    log(`${label} K1b`, {
      errorShown: !!screen.queryByText('Invalid email'),
      rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
    });
    cleanup();
  });

  it('K2: onBlur validation (async) + consumer normalizes the value in onBlur', async () => {
    const seen: unknown[] = [];
    const resolvers: Array<(r: string | null) => void> = [];
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root
          data-testid="root"
          validationMode="onBlur"
          validate={(v) => {
            seen.push(v);
            return new Promise<string | null>((resolve) => {
              resolvers.push(resolve);
            });
          }}
        >
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            onBlur={() => setValue((v) => v.trim())}
          />
          <Field.Error />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.focus(control);
    fireEvent.change(control, { target: { value: 'taken ' } });
    fireEvent.blur(control);
    await act(async () => {
      resolvers.forEach((resolve) => resolve('Name is taken'));
      await Promise.resolve();
      await Promise.resolve();
    });
    log(`${label} K2`, {
      validateCalls: seen,
      inputValue: control.value,
      errorShown: !!screen.queryByText('Name is taken'),
      rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
    });
    cleanup();
  });

  it('E2: server error held in state, then a programmatic controlled change', () => {
    let set: (v: string) => void = () => {};
    const errors = { message: 'Server error' };
    function App() {
      const [value, setValue] = React.useState('');
      set = setValue;
      return (
        <Form errors={errors}>
          <Field.Root name="message">
            <Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const before = !!screen.queryByText('Server error');
    act(() => set('from code'));
    log(`${label} E2`, {
      errorBefore: before,
      errorAfterProgrammaticSet: !!screen.queryByText('Server error'),
    });
    cleanup();
  });

  it('E3: server error and value rewrite land in the same commit, then in separate commits', () => {
    let apply: (errors: Record<string, string>, v?: string) => void = () => {};
    let set: (v: string) => void = () => {};
    function App() {
      const [value, setValue] = React.useState('a');
      const [errors, setErrors] = React.useState<Record<string, string>>({});
      set = setValue;
      apply = (nextErrors, v) => {
        setErrors(nextErrors);
        if (v !== undefined) {
          setValue(v);
        }
      };
      return (
        <Form errors={errors}>
          <Field.Root name="message">
            <Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    act(() => apply({ message: 'Server error' }, 'normalized'));
    const sameCommit = !!screen.queryByText('Server error');
    act(() => set('normalized again'));
    const laterCommit = !!screen.queryByText('Server error');
    log(`${label} E3`, { errorAfterSameCommit: sameCommit, errorAfterLaterValueChange: laterCommit });
    cleanup();
  });

  it('M: required controlled field reset to empty from onFormSubmit', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form onFormSubmit={() => setValue('')}>
          <Field.Root name="message" data-testid="root">
            <Control data-testid="control" required value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.change(control, { target: { value: 'hello' } });
    fireEvent.click(screen.getByText('submit'));
    const root = screen.getByTestId('root');
    log(`${label} M`, {
      inputValue: control.value,
      rootInvalid: root.hasAttribute('data-invalid'),
      rootDirty: root.hasAttribute('data-dirty'),
      rootFilled: root.hasAttribute('data-filled'),
      errorText: screen.queryByTestId('error')?.textContent ?? null,
    });
    cleanup();
  });
});

