import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseControl } from './FieldControlBase';

afterEach(() => cleanup());
const flush = () => act(async () => { await Promise.resolve(); });
const out: Record<string, unknown> = {};
const SERVER_ERRORS = { message: 'Server error' };
const variants: Array<[string, any]> = [['head', Field.Control], ['base', BaseControl]];

for (const [label, Control] of variants) {
  it(`${label} F1 submit then clear`, async () => {
    function App() {
      const [v, setV] = React.useState('');
      return (
        <Form data-testid="form" onFormSubmit={() => setV('')}>
          <Field.Root name="title" data-testid="root">
            <Control required value={v} onValueChange={setV} data-testid="c" />
            <Field.Error data-testid="err" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const c = screen.getByTestId('c') as HTMLInputElement;
    fireEvent.change(c, { target: { value: 'abc' } });
    await flush();
    fireEvent.submit(screen.getByTestId('form'));
    await flush();
    out[`${label}.F1`] = {
      inputValue: c.value,
      rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
      ariaInvalid: c.getAttribute('aria-invalid'),
      err: screen.queryByTestId('err')?.textContent ?? null,
    };
  });

  it(`${label} F3 focus then disable / unmount`, async () => {
    function App({ disabled, show }: { disabled: boolean; show: boolean }) {
      return (
        <Field.Root data-testid="root">
          {show ? <Control data-testid="c" disabled={disabled} /> : null}
        </Field.Root>
      );
    }
    const r = render(<App disabled={false} show />);
    fireEvent.focus(screen.getByTestId('c'));
    const before = screen.getByTestId('root').hasAttribute('data-focused');
    r.rerender(<App disabled show />);
    await flush();
    const afterDisable = screen.getByTestId('root').hasAttribute('data-focused');
    cleanup();
    const r2 = render(<App disabled={false} show />);
    fireEvent.focus(screen.getByTestId('c'));
    const before2 = screen.getByTestId('root').hasAttribute('data-focused');
    r2.rerender(<App disabled={false} show={false} />);
    await flush();
    out[`${label}.F3`] = {
      before, afterDisable, before2,
      afterUnmount: screen.getByTestId('root').hasAttribute('data-focused'),
    };
  });

  it(`${label} F4 value loaded while disabled`, async () => {
    function App() {
      const [s, setS] = React.useState({ v: '', disabled: true });
      return (
        <Field.Root data-testid="root">
          <Control value={s.v} disabled={s.disabled} onValueChange={(v: string) => setS({ v, disabled: false })} data-testid="c" />
          <button onClick={() => setS({ v: 'loaded', disabled: false })}>load</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('load'));
    await flush();
    const c = screen.getByTestId('c') as HTMLInputElement;
    const dirtyAfterLoad = screen.getByTestId('root').hasAttribute('data-dirty');
    fireEvent.change(c, { target: { value: 'loadedX' } });
    const dirtyAfterEdit = screen.getByTestId('root').hasAttribute('data-dirty');
    fireEvent.change(c, { target: { value: 'loaded' } });
    out[`${label}.F4`] = {
      inputValue: c.value, dirtyAfterLoad, dirtyAfterEdit,
      dirtyAfterReturnToLoaded: screen.getByTestId('root').hasAttribute('data-dirty'),
    };
  });

  for (const rewrite of [true, false]) {
    it(`${label} F5 blur validation, rewrite=${rewrite}`, async () => {
      const calls: unknown[] = [];
      const validate = (v: unknown) => { calls.push(v); return String(v).length < 6 ? 'too short' : null; };
      function App() {
        const [v, setV] = React.useState('');
        return (
          <Field.Root data-testid="root" validationMode="onBlur" validate={validate}>
            <Control value={v} onValueChange={setV} data-testid="c"
              onBlur={rewrite ? () => setV((p) => p.trim()) : undefined} />
            <Field.Error data-testid="err" />
          </Field.Root>
        );
      }
      render(<App />);
      const c = screen.getByTestId('c') as HTMLInputElement;
      fireEvent.focus(c);
      fireEvent.change(c, { target: { value: 'foo ' } });
      fireEvent.blur(c);
      await flush();
      out[`${label}.F5.rewrite=${rewrite}`] = {
        inputValue: c.value, calls,
        rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid'),
        rootValid: screen.getByTestId('root').hasAttribute('data-valid'),
        err: screen.queryByTestId('err')?.textContent ?? null,
      };
    });
  }

  for (const mode of ['onChange', undefined] as const) {
    it(`${label} F6 render count mode=${mode}`, async () => {
      let count = 0;
      const log: unknown[] = [];
      function App() {
        const [v, setV] = React.useState('');
        return (
          <Field.Root validationMode={mode} validate={mode ? () => null : undefined}>
            <Control data-testid="c" value={v} onValueChange={setV}
              render={(props: any, state: any) => { count += 1; log.push([props.value, state.valid, state.dirty]); return <input {...props} />; }} />
          </Field.Root>
        );
      }
      render(<App />);
      const c = screen.getByTestId('c');
      const c0 = count;
      fireEvent.change(c, { target: { value: 'a' } });
      const c1 = count;
      fireEvent.change(c, { target: { value: 'ab' } });
      const c2 = count;
      fireEvent.change(c, { target: { value: 'abc' } });
      out[`${label}.F6.mode=${mode}`] = { first: c1 - c0, second: c2 - c1, third: count - c2, log: log.slice(-4) };
    });
  }

  for (const kind of ['prevented', 'canceled'] as const) {
    it(`${label} F7 controlled ${kind}`, async () => {
      let validateCalls = 0;
      const validate = () => { validateCalls += 1; return null; };
      function App() {
        const [v, setV] = React.useState('');
        return (
          <Form errors={SERVER_ERRORS}>
            <Field.Root name="message" validationMode="onChange" validate={validate}>
              <Control data-testid="c" value={v}
                onValueChange={(next: string, details: any) => { if (kind === 'canceled') { details.cancel(); } setV(next); }} />
              <Field.Error data-testid="err" />
            </Field.Root>
          </Form>
        );
      }
      render(<App />);
      const c = screen.getByTestId('c') as HTMLInputElement;
      const errBefore = screen.queryByTestId('err')?.textContent ?? null;
      if (kind === 'prevented') {
        c.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
        fireEvent.input(c, { cancelable: true, target: { value: 'a' } });
      } else {
        fireEvent.change(c, { target: { value: 'a' } });
      }
      await flush();
      out[`${label}.F7.${kind}`] = { inputValue: c.value, validateCalls, errBefore, errAfter: screen.queryByTestId('err')?.textContent ?? null };
    });
  }

  it(`${label} F8 remount with empty value`, async () => {
    function App() {
      const [s, setS] = React.useState({ v: 'abc', show: true });
      return (
        <Field.Root data-testid="root">
          {s.show ? <Control data-testid="c" value={s.v} onValueChange={(v: string) => setS({ v, show: true })} /> : null}
          <button onClick={() => setS({ v: '', show: false })}>hide</button>
          <button onClick={() => setS((p) => ({ ...p, show: true }))}>show</button>
        </Field.Root>
      );
    }
    render(<App />);
    const filledInitially = screen.getByTestId('root').hasAttribute('data-filled');
    fireEvent.click(screen.getByText('hide'));
    await flush();
    fireEvent.click(screen.getByText('show'));
    await flush();
    out[`${label}.F8`] = {
      filledInitially, inputValue: (screen.getByTestId('c') as HTMLInputElement).value,
      filledAfterRemount: screen.getByTestId('root').hasAttribute('data-filled'),
    };
  });
}

it('dump', () => {
  // eslint-disable-next-line no-console
  console.log('RESULTS ' + JSON.stringify(out, null, 1));
});
